    "REPLACE ALL COVERS?" to Tr(ja = "カバーを ぜんぶ いれかえますか?", fr = "REMPLACER TOUTES LES JAQUETTES ?", de = "ALLE COVER ERSETZEN?", it = "SOSTITUIRE TUTTE LE COPERTINE?", es = "¿REEMPLAZAR TODAS LAS PORTADAS?"),
    "Fetches new art from SteamGridDB for every ROM, replacing current covers (manually set ones too). A ROM with no art found keeps its cover." to Tr(ja = "SteamGridDBから すべての ROMの あたらしい がぞうを とってきて いまの カバーと いれかえます(じぶんで えらんだ ものも)。 がぞうが みつからない ROMは いまの カバーの ままです。", fr = "Récupère de nouvelles images sur SteamGridDB pour chaque ROM et remplace les jaquettes actuelles (même celles choisies à la main). Une ROM sans image trouvée garde sa jaquette.", de = "Lädt für jede ROM neue Bilder von SteamGridDB und ersetzt die aktuellen Cover (auch manuell gesetzte). Eine ROM ohne gefundenes Bild behält ihr Cover.", it = "Scarica nuove immagini da SteamGridDB per ogni ROM, sostituendo le copertine attuali (anche quelle scelte a mano). Una ROM senza immagini trovate mantiene la sua copertina.", es = "Descarga nuevas imágenes de SteamGridDB para cada ROM y reemplaza las portadas actuales (también las elegidas a mano). Una ROM sin imágenes encontradas conserva su portada."),
    "REPLACE" to Tr(ja = "いれかえる", fr = "REMPLACER", de = "ERSETZEN", it = "SOSTITUISCI", es = "REEMPLAZAR"),

    // Hotkeys / game buttons
    "Tap a hotkey, then press one or more keys/buttons together and release — e.g. hold Select and tap R1 for a chord. BACK cancels." to Tr(ja = "ホットキーを タップして、 キーや ボタンを 1つか いくつか いっしょに おして はなします — たとえば Selectを おしたまま R1を おすと くみあわせに なります。 BACKで キャンセル。", fr = "Touchez un raccourci, puis appuyez sur une ou plusieurs touches ensemble et relâchez — ex. maintenez Select et appuyez sur R1 pour une combinaison. BACK annule.", de = "Tippe auf einen Hotkey, drücke dann eine oder mehrere Tasten zusammen und lass los — z. B. Select halten und R1 tippen für eine Kombination. BACK bricht ab.", it = "Tocca un tasto rapido, poi premi insieme uno o più tasti e rilascia — es. tieni Select e premi R1 per una combinazione. BACK annulla.", es = "Toca un atajo, luego pulsa una o más teclas a la vez y suelta — p. ej. mantén Select y pulsa R1 para una combinación. BACK cancela."),
    "PRESS KEYS…" to Tr(ja = "キーを おして…", fr = "APPUYEZ…", de = "TASTEN DRÜCKEN…", it = "PREMI I TASTI…", es = "PULSA TECLAS…"),
    "Which physical button is each GBA button. The D-pad and analog stick are fixed." to Tr(ja = "GBAの それぞれの ボタンに どの ボタンを つかうか。 じゅうじキーと スティックは かえられません。", fr = "Quel bouton physique correspond à chaque bouton GBA. La croix et le stick analogique sont fixes.", de = "Welche echte Taste jede GBA-Taste ist. Steuerkreuz und Analogstick sind fest.", it = "Quale tasto fisico corrisponde a ogni tasto GBA. Croce direzionale e levetta analogica sono fissi.", es = "Qué botón físico es cada botón de GBA. La cruceta y el stick analógico son fijos."),
